// Drawn, not brand marks: Context7 has no published logo, Playwright's is not
// single-colour, and "browser" is a kind of thing, not a brand.
const globe = <><circle cx="12" cy="12" r="8.5" /><path d="M3.5 12h17M12 3.5c2.5 2.6 3.5 5.5 3.5 8.5s-1 5.9-3.5 8.5c-2.5-2.6-3.5-5.5-3.5-8.5s1-5.9 3.5-8.5z" /></>;
const GLYPHS = {
  context7: <><path d="M5 4.5h9.5a3 3 0 013 3V20H8a3 3 0 01-3-3z" /><path d="M5 17a3 3 0 013-3h9.5" /></>,
  playwright: globe,
  browser: globe,
  skill: <path d="M12 3.5l1.9 5.1 5.1 1.9-5.1 1.9L12 17.5l-1.9-5.1L5 10.5l5.1-1.9zM18 15.5l.8 2.2 2.2.8-2.2.8-.8 2.2-.8-2.2-2.2-.8 2.2-.8z" />,
  plugin: <path d="M9.5 4.5a2 2 0 014 0V6H17a1 1 0 011 1v3.5h-1.5a2 2 0 000 4H18V18a1 1 0 01-1 1h-3.5v-1.5a2 2 0 00-4 0V19H6a1 1 0 01-1-1v-3.5h1.5a2 2 0 000-4H5V7a1 1 0 011-1h3.5z" />,
};
type Glyph = keyof typeof GLYPHS;
const TINTS = ['#7c8cf8', '#3fb68b', '#e0a43a', '#e5677d', '#4fa3e0', '#a77be8', '#5fb7b0', '#d9825b'];

// Other words for a brand. Short or everyday words stay out, so "example"
// never reads as a service and "drive" alone never reads as Google Drive.
const ALIASES: Record<string, string> = {
  gdrive: 'google-drive', postgresql: 'postgres', mongo: 'mongodb', k8s: 'kubernetes', kubectl: 'kubernetes',
  confluence: 'atlassian', 'chrome-devtools': 'chrome', 'brave-search': 'brave', githubcopilot: 'github',
  codex: 'openai', chatgpt: 'openai', anthropic: 'claude', 'anthropic-ai': 'claude', 'claude-code': 'claude',
  modelcontextprotocol: 'mcp', gmailmcp: 'gmail', drivemcp: 'google-drive', calendarmcp: 'google-calendar',
};
// What runs a command says little about the service behind it, so these
// marks come from the command or the package, never from a name.
const RUNTIMES = new Set(['node', 'bun', 'deno', 'python', 'docker', 'mcp']);
const RUNNERS: [RegExp, string][] = [
  [/^(node|nodejs|npx|npm|pnpm|yarn|tsx|ts-node)$/, 'node'], [/^(bun|bunx)$/, 'bun'], [/^deno$/, 'deno'],
  [/^(python[\d.]*|pip[\d.]*|pipx|uv|uvx|poetry|pdm)$/, 'python'], [/^(docker|podman)$/, 'docker'],
];

const words = (text: string) => `-${text.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-`;
const KEYS = [...Object.keys(MARKS), ...Object.keys(GLYPHS), ...Object.keys(ALIASES)].filter((k) => k !== 'skill' && k !== 'plugin');
/** The brand a name, address or package spells out as a whole word, if any. */
function spelled(text = '', runtimes = false): string | undefined {
  const w = words(text);
  const found = KEYS.filter((k) => w.includes(`-${k}-`)).map((k) => ALIASES[k] ?? k).filter((k) => runtimes || !RUNTIMES.has(k));
  // "@modelcontextprotocol/server-github" is GitHub; MCP only when nothing else is named.
  return found.find((k) => k !== 'mcp') ?? found[0];
}
/** The runtime or vendor behind a command, from the program it starts. */
function runner(command: string): string | undefined {
  const path = command.toLowerCase();
  // A program inside an app's own folder belongs to that app.
  if (/\/(chatgpt|openai|codex)[/.-]|\/\.codex\//.test(path)) return 'openai';
  if (/\/(claude|anthropic)[/.-]|@anthropic-ai\//.test(path)) return 'claude';
  if (/\/omarchy\//.test(path)) return 'omarchy';
  const bin = path.split('/').pop() ?? '';
  const known = RUNNERS.find(([re]) => re.test(bin))?.[1];
  if (known) return known;
  if (/\/(node_modules|\.npm|\.bun|\.nvm)\//.test(path)) return 'node';
  if (/\/(site-packages|\.venv|venv|\.local\/share\/uv)\//.test(path)) return 'python';
  return undefined;
}

export type Logo = { key?: string; by?: 'name' | 'address' | 'package' | 'command' | 'owner' };
/** What a connector's tile shows and why: the service it reaches, else what runs it. */
export function connectorLogo(name: string, target = '', pkg = ''): Logo {
  let host = '';
  try { host = new URL(target).hostname; } catch { /* a command, not an address */ }
  let key = spelled(name);
  if (key) return { key, by: 'name' };
  if ((key = host ? spelled(host) : spelled(pkg, true))) return { key, by: host ? 'address' : 'package' };
  if ((key = host ? undefined : runner(target) ?? spelled(name, true))) return { key, by: 'command' };
  return {};
}
/** A connector's title: the brand's name when it plainly is that service, else its own name. */
export const brandTitle = (name: string, target?: string, pkg?: string) => {
  const { key, by } = connectorLogo(name, target, pkg), exact = words(name).slice(1, -1);
  return key && MARKS[key] && (by === 'address' || (by === 'name' && exact === key)) ? MARKS[key].title : name;
};
/** A plugin's brand by its own name, else its marketplace's vendor. */
export function pluginLogo(fullName: string): Logo {
  const [name, market = ''] = fullName.split('@');
  const own = spelled(name);
  if (own) return { key: own, by: 'name' };
  const vendor = /^(openai|codex|chatgpt)\b/i.test(market) ? 'openai' : /^(claude|anthropic)\b/i.test(market) ? 'claude' : spelled(market);
  return vendor ? { key: vendor, by: 'owner' } : {};
}
/** A skill's brand by its name or the folder it really lives in, else the CLI that owns it. */
export function skillLogo(name: string, source = '', engine = ''): Logo {
  const own = spelled(name) ?? (/\/omarchy\//.test(source) ? 'omarchy' : undefined);
  if (own) return { key: own, by: 'name' };
  return ['claude', 'codex'].includes(engine) ? { key: engine === 'codex' ? 'openai' : 'claude', by: 'owner' } : {};
}

export function ConnectorLogo({ name, target, pkg, source, engine, kind = 'connector', size = 32 }: {
  name: string; target?: string; pkg?: string; source?: string; engine?: string; kind?: 'connector' | 'skill' | 'plugin'; size?: number;
}) {
  const { key } = kind === 'connector' ? connectorLogo(name, target, pkg) : kind === 'plugin' ? pluginLogo(name) : skillLogo(name, source, engine);
  const mark = key ? MARKS[key] : undefined;
  const glyph = key && !mark ? GLYPHS[key as Glyph] : kind !== 'connector' ? GLYPHS[kind] : undefined;
  let hash = 0;
  for (const ch of name) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  const tint = mark ? mark.color : kind === 'skill' ? 'var(--primary-q)' : kind === 'connector' && !glyph ? TINTS[hash % TINTS.length] : undefined;
  const style = { width: size, height: size, ...(tint ? { '--tint': tint } : {}) } as CSSProperties;
  return <span className={`clogo${tint ? ' tinted' : ''}`} style={style} title={mark?.title} aria-hidden="true" data-logo={key ?? (glyph ? kind : 'letter')}>
    {mark ? <svg viewBox={mark.view ?? '0 0 24 24'} width={size * 0.55} height={size * 0.55} fill="currentColor" fillRule={mark.evenodd ? 'evenodd' : undefined}><path d={mark.d} /></svg>
      : glyph ? <svg viewBox="0 0 24 24" width={size * 0.6} height={size * 0.6} fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">{glyph}</svg>
      : <span className="clogo-letter">{(name.match(/[a-z0-9]/i)?.[0] ?? '?').toUpperCase()}</span>}
  </span>;
}
